{
  "needsDevelopment": false,
  "proposal": {
    "resources": [],
    "ecology": [],
    "mechanics": [
      {
        "id": "examine-natural-material",
        "name": "Examine natural material",
        "description": "Examine an owned or adjacent stack without consuming it, learning its true type properties, including nutrition and toxicity. An adjacent natural site can instead be examined to reveal its remaining stock. Examination does not prepare food, remove hazards, or establish a preparation recipe.",
        "parameters": [
          "itemId"
        ],
        "code": "[{\"op\":\"identify\",\"target\":\"itemId\",\"resource\":null,\"quantity\":1,\"costs\":[],\"tool\":null,\"chance\":100}]"
      }
    ],
    "reviews": [
      {
        "agentId": "lin",
        "decision": "reject",
        "reason": "The requested automatic examine-and-eat transaction cannot be implemented faithfully: available operations cannot condition consumption on newly revealed properties or branch between a loose item and a tree. Combining identification with consumption would eat harmful material too. Examination, harvesting from verified stock, and eating must be separate requested capabilities and uses; a standing tree does not itself establish edible stock.",
        "prerequisites": [
          "Separate examination from consumption so the examination result can be evaluated before eating.",
          "Consumption requires an owned edible stack.",
          "Harvesting requires a reachable site with actual stock of the specified resource."
        ],
        "learningRounds": 0,
        "mechanicId": null
      },
      {
        "agentId": "sol",
        "decision": "create",
        "reason": "Non-consuming examination is feasible and reveals the examined type's nutritional and harmful properties. It does not invent safe preparation methods; any preparation requires a separately supported recipe.",
        "prerequisites": [
          "An owned stack or an adjacent visible stack to examine.",
          "No tool or expendable material is required."
        ],
        "learningRounds": 2,
        "mechanicId": "examine-natural-material"
      },
      {
        "agentId": "reed",
        "decision": "create",
        "reason": "This is equivalent to the examination ability proposed for Sol, with learning undertaken independently. It reveals the examined mushroom type's properties without ingestion, but does not establish or perform a preparation method.",
        "prerequisites": [
          "An owned mushroom stack or an adjacent visible mushroom stack.",
          "No tool or expendable material is required."
        ],
        "learningRounds": 2,
        "mechanicId": "examine-natural-material"
      }
    ]
  }
}

{
  "needsDevelopment": false,
  "proposal": {
    "resources": [],
    "ecology": [],
    "mechanics": [
      {
        "id": "foodassessment",
        "name": "Examine food",
        "description": "Examine an owned or adjacent stack to learn its true type properties without consuming it. An adjacent natural site can instead be examined to reveal remaining stock. Examination does not prepare food, remove hazards, or establish a preparation recipe.",
        "parameters": [
          "target"
        ],
        "code": "[{\"op\":\"identify\",\"target\":\"target\",\"resource\":null,\"quantity\":1,\"costs\":[],\"tool\":null,\"chance\":100}]"
      }
    ],
    "reviews": [
      {
        "agentId": "lin",
        "decision": "reject",
        "reason": "Examination, harvesting actual stock, and eating are individually feasible, but the requested automatic safety-gated combination cannot be implemented with the available operations: identification cannot conditionally prevent a following consumption operation. Trees also cannot be assumed to contain food. Request examination and separate harvesting or eating capabilities rather than an automatic examine-and-eat transaction.",
        "prerequisites": [
          "Examination requires an owned or adjacent stack, or an adjacent natural site.",
          "Harvesting requires actual matching food stock at a reachable site.",
          "Eating requires owned food; any safety decision must occur after examination and before a separate consumption action."
        ],
        "learningRounds": 0,
        "mechanicId": null
      },
      {
        "agentId": "sol",
        "decision": "create",
        "reason": "Non-consuming examination is supported and reveals the examined type's nutrition and harmful properties. It does not discover an unspecified safe preparation or guarantee that preparation can remove a hazard.",
        "prerequisites": [
          "An owned or adjacent stack to examine.",
          "No tools or material expenditure."
        ],
        "learningRounds": 2,
        "mechanicId": "foodassessment"
      },
      {
        "agentId": "reed",
        "decision": "create",
        "reason": "The same non-consuming examination mechanic applies to mushrooms. It reveals the examined type's actual properties, but does not prepare it or promise that a safe preparation exists.",
        "prerequisites": [
          "An owned or adjacent mushroom stack to examine.",
          "No tools or material expenditure."
        ],
        "learningRounds": 2,
        "mechanicId": "foodassessment"
      }
    ]
  }
}

