      }
    ],
    "ecology": [
      {
        "id": "silver-fish-river-reaches",
        "resource": "silver-river-fish",
        "siteKind": "water",
        "biomes": [
          "river",
          "shallow"
        ],
        "distribution": [
          0,
          0,
          1,
          1
        ],
        "reason": "River reaches can support small fish, but patchy cover and variable aquatic habitat leave some reaches empty. Allocate stock once within site capacity and energy limits, only where no prior ecological allocation exists; stock does not replenish."
      }
    ],
    "mechanics": [
      {
        "id": "hand-catch-river-fish",
        "name": "Bank hand fishing",
        "description": "Attempt to catch one small silver river fish within arm's reach at an adjacent water site's margin. This can be attempted from an adjacent bank without entering the river, but bare-handed capture is unreliable: each attempt has a 25% success chance. Requires finite matching stock; empty or exhausted sites yield nothing. Success transfers one fish into owned inventory without consuming it or identifying its properties. Failure spends the round without removing stock.",
        "parameters": [
          "target"
        ],
        "code": "[{\"op\":\"extract\",\"target\":\"target\",\"resource\":\"silver-river-fish\",\"quantity\":1,\"costs\":[],\"tool\":null,\"chance\":25}]"
      }
    ],
    "reviews": [
      {
        "agentId": "moss",
        "decision": "create",
        "reason": "Opportunistic bare-handed capture at a river margin is feasible without entering deep water, but limited reach and evasive fish make it unreliable. This ability does not guarantee that the examined reach supports fish or that a caught fish is safe to eat. Learning patient approach and hand placement takes four rounds.",
        "prerequisites": [
          "Specify an adjacent water site as target; successful extraction requires at least one silver river fish remaining in its stock.",
          "For the requested bank-side approach, remain on passable land adjacent to the target.",
          "No tools or material costs are required; each attempt has a 25% success chance and spends a round even when unsuccessful.",
          "Examination and consumption are separate abilities."
        ],
        "learningRounds": 4,
        "mechanicId": "hand-catch-river-fish"
      }
    ]
  }
}

